    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: Which of the following coagulation factors does NOT increase during pregnancy?', '["Fibrinogen (Factor I)", "Factor VII", "Factor VIII", "Factor XI and XIII"]', 3, 'Factors XI and XIII actually decrease slightly. Pregnancy is generally a hypercoagulable state due to increases in I, VII, VIII, IX, and X. (Gabbe)'),
    (v_topic_id, '102: Pregnancy is considered a pro-thrombotic state. By how much does the risk of venous thromboembolism (VTE) increase compared to non-pregnant women?', '["2 times", "5 to 10 times", "50 times", "No increase"]', 1, 'The risk is elevated throughout pregnancy and is highest in the postpartum period. (ACOG)'),
    (v_topic_id, '103: Which gastrointestinal change in pregnancy increases the risk of gallstone formation?', '["Increased bile production", "Incomplete emptying of the gallbladder due to progesterone", "Decreased cholesterol saturation", "Hyperactive gut motility"]', 1, 'Progesterone causes smooth muscle relaxation, leading to gallbladder stasis. (Williams)'),
    (v_topic_id, '104: What is the "Goodell sign"?', '["Softening of the cervix", "Bluish discoloration of the vagina", "Softening of the lower uterine segment", "Cervical dilation"]', 0, 'Observed around 4-6 weeks gestation. (Beckmann)'),
    (v_topic_id, '105: "Hegar sign" is characterized by:', '["Dilation of the internal os", "Softening of the lower uterine segment (isthmus)", "Rupture of membranes", "Fetal descent"]', 1, 'Softening allows the uterus to be easily compressed during bimanual exam. (Gabbe)'),
    (v_topic_id, '106: Why is there an increased risk of urinary tract infections in pregnancy?', '["Mechanical compression of the ureters by the uterus", "Progesterone-induced relaxation of ureteral smooth muscle", "Glycosuria and alkaline urine", "All of the above"]', 3, 'These factors combine to promote urinary stasis and bacterial growth. (ACOG)'),
    (v_topic_id, '107: Which of the following is the most common cause of hyperthyroidism in pregnancy?', '["Graves disease", "Toxic multinodular goiter", "Gestational transient thyrotoxicosis (hCG-mediated)", "Thyroid storm"]', 2, 'hCG-mediated stimulation of the TSH receptor is common and usually mild/transient. (Williams)'),
    (v_topic_id, '108: For a woman with pre-existing hypothyroidism, how should her levothyroxine dose typically change once pregnancy is confirmed?', '["Decrease by 25%", "No change", "Increase by 30-50%", "Stop medication until the 2nd trimester"]', 2, 'Requirement for thyroid hormone increases early in the 1st trimester. (ACOG)'),
    (v_topic_id, '109: What is the primary role of "Human Placental Lactogen" (hPL), also known as human chorionic somatomammotropin?', '["To induce labor", "To ensure a steady supply of glucose to the fetus by inducing maternal insulin resistance", "To maintain the corpus luteum", "To stimulate milk production during pregnancy"]', 1, 'hPL is a growth hormone-like antagonist to insulin. (Gabbe)'),
    (v_topic_id, '110: Which placental hormone is the most reliable marker of placental function and fetal well-being in some research contexts, though not used in routine clinical screening?', '["hCG", "Estriol (uE3)", "Progesterone", "Cortisol"]', 1, 'Estriol requires a functioning fetal liver and adrenal glands. (Williams)'),
    (v_topic_id, '111: A woman at 12 weeks gestation presents with vaginal bleeding and an open cervical os. No tissue has passed yet. Diagnosis?', '["Threatened abortion", "Inevitable abortion", "Incomplete abortion", "Missed abortion"]', 1, 'Bleeding + open os = Inevitable. If the os were closed, it would be Threatened. (Beckmann)'),
    (v_topic_id, '112: A woman at 8 weeks gestation has vaginal bleeding, an open os, and some tissue has passed. Some remains in the uterus. Diagnosis?', '["Threatened abortion", "Complete abortion", "Incomplete abortion", "Septic abortion"]', 2, 'Requires evacuation (D&C or Misoprostol) if not resolving. (ACOG)'),
    (v_topic_id, '113: A "Missed Abortion" is defined as:', '["Death of the fetus in utero with retention of the products of conception and a closed os", "Expulsion of all fetal tissue", "Fetal death due to infection", "Ectopic pregnancy"]', 0, 'Often found incidentally on ultrasound when fetal heart tones are absent. (Williams)'),
    (v_topic_id, '114: Which of the following is a risk factor for recurrent spontaneous abortion (3 or more consecutive losses)?', '["Antiphospholipid syndrome", "Parental balanced translocation", "Uterine septum", "All of the above"]', 3, 'Requires a specialized workup. (Gabbe)'),
    (v_topic_id, '115: What is the definitive treatment for a "Septic Abortion"?', '["Oral antibiotics only", "IV antibiotics and immediate uterine evacuation (D&E)", "Expectant management", "Hysterectomy"]', 1, 'Infection of the uterine contents is a medical emergency. (ACOG)'),
    (v_topic_id, '116: Which of the following is the most common maternal complication of a multiple gestation?', '["Anemia", "Gestational diabetes", "Pre-eclampsia", "All of the above"]', 3, 'Multiple gestations put significant strain on the mother''s physiology. (Williams)'),
    (v_topic_id, '117: In a twin pregnancy, what does the "Twin Peak" or "Lambda" sign on ultrasound indicate?', '["Monochorionic diamniotic twins", "Dichorionic diamniotic twins", "Monochorionic monoamniotic twins", "Conjoined twins"]', 1, 'Indicates two separate placentas that have fused. (ACOG)'),
    (v_topic_id, '118: "Twin-to-Twin Transfusion Syndrome" (TTTS) occurs exclusively in:', '["Dichorionic twins", "Monochorionic twins", "Fraternal twins", "All multiples"]', 1, 'Due to vascular anastomoses in a single shared placenta. (Gabbe)'),
    (v_topic_id, '119: What is the primary ultrasound finding in the "Donor" twin in TTTS?', '["Polyhydramnios and large size", "Oligohydramnios and small size (anemia)", "Macrosomia", "Hydrops"]', 1, 'The donor shunts blood to the recipient. (Williams)'),
    (v_topic_id, '120: Which of the following is a classic clinical sign of an ectopic pregnancy?', '["Painless bleeding", "Abdominal pain, amenorrhea, and vaginal bleeding", "High fever", "Hyperemesis"]', 1, 'The "classic triad" is present in about 50% of cases. (Beckmann)'),
    (v_topic_id, '121: In a stable patient with a suspected ectopic pregnancy, what is the significance of a "pseudogestational sac" on ultrasound?', '["It confirms an intrauterine pregnancy", "It is a collection of fluid in the uterus that can mimic a sac in ectopic pregnancy", "It indicates twins", "It suggests a molar pregnancy"]', 1, 'Does not contain a yolk sac or embryo. (Gabbe)'),
    (v_topic_id, '122: What is the "Double Decidual Sign"?', '["A sign of twins", "Two layers of the decidua seen on US, confirming an early IUP", "A sign of miscarriage", "Placental abruption"]', 1, 'Helps differentiate a true gestational sac from a pseudosac. (Williams)'),
    (v_topic_id, '123: Which of the following is a contraindication to Methotrexate therapy for ectopic pregnancy?', '["hCG level < 5000", "Fetal cardiac activity", "Patient compliance", "Absence of adnexal mass"]', 1, 'Relative contraindications include high hCG, large mass, and fetal heart tones. Absolute include rupture or breastfeeding. (ACOG)'),
    (v_topic_id, '124: "Cervical Insufficiency" typically presents as:', '["Painful contractions in the 1st trimester", "Painless cervical dilation and second-trimester pregnancy loss", "Heavy bleeding", "High fever"]', 1, 'Often managed with a cervical cerclage in subsequent pregnancies. (Beckmann)'),
    (v_topic_id, '125: At what gestational age is a cervical "Cerclage" typically placed in a woman with a history of cervical insufficiency?', '["8 weeks", "12-14 weeks", "24 weeks", "At delivery"]', 1, 'Placed before the second trimester when most losses occur. (Williams)'),
    (v_topic_id, '126: Which of the following is a maternal risk of Gestational Diabetes?', '["Increased risk of developing Type 2 Diabetes later in life", "Polyhydramnios", "Pre-eclampsia", "All of the above"]', 3, 'Requires postpartum follow-up with a 75g GTT. (ACOG)'),
    (v_topic_id, '127: Fetal "Macrosomia" is defined as a birth weight greater than:', '["3500 grams", "4000-4500 grams", "5000 grams", "None of the above"]', 1, 'Increases risk of shoulder dystocia and C-section. (ACOG)'),
    (v_topic_id, '128: Which of the following fetal anomalies is specifically associated with PRE-GESTATIONAL diabetes (Type 1 or 2) but NOT with gestational diabetes?', '["Macrosomia", "Caudal regression syndrome and heart defects", "Polyhydramnios", "Neonatal hypoglycemia"]', 1, 'Congenital malformations occur during organogenesis (first 8 weeks), before GDM typically develops. (Gabbe)'),
    (v_topic_id, '129: What is the "Gold Standard" for diagnosing gestational diabetes if the 1-hour screen is abnormal?', '["Fast for 24 hours", "3-hour 100g Glucose Tolerance Test (GTT)", "HbA1c level", "Random blood glucose"]', 1, 'Two or more abnormal values on the 3-hour test confirm GDM. (ACOG)'),
    (v_topic_id, '130: First-line medical therapy for gestational diabetes when diet and exercise fail is:', '["Metformin", "Insulin", "Glyburide", "Acarbose"]', 1, 'Insulin does not cross the placenta and is the preferred agent. (ACOG)'),
    (v_topic_id, '131: A "Non-Stress Test" (NST) measures:', '["Fetal heart rate response to contractions", "Fetal heart rate response to fetal movement", "Maternal blood pressure", "Amniotic fluid volume"]', 1, 'Used to assess fetal acid-base status and oxygenation. (Beckmann)'),
    (v_topic_id, '132: In an NST, what is a "Deceleration"?', '["A temporary increase in fetal HR", "A temporary decrease in fetal HR below the baseline", "A sign of fetal sleep", "Normal during movement"]', 1, 'The type of deceleration (early, late, variable) indicates the underlying cause. (ACOG)'),
    (v_topic_id, '133: "Early Decelerations" on fetal monitoring are caused by:', '["Uteroplacental insufficiency", "Umbilical cord compression", "Fetal head compression", "Maternal hypotension"]', 2, 'Mirror the contraction; benign. (Williams)'),
    (v_topic_id, '134: "Late Decelerations" on fetal monitoring are caused by:', '["Head compression", "Uteroplacental insufficiency", "Cord compression", "Fetal sleep"]', 1, 'Start after the peak of the contraction; non-reassuring if recurrent. (Gabbe)'),
    (v_topic_id, '135: "Variable Decelerations" on fetal monitoring are caused by:', '["Cord compression", "Head compression", "Placental abruption", "Maternal fever"]', 0, 'Abrupt drop and return; often corrected with maternal position change. (ACOG)'),
    (v_topic_id, '136: A "Contraction Stress Test" (CST) is considered "Positive" (abnormal) if:', '["Accelerations are present", "Late decelerations follow 50% or more of contractions", "No decelerations are seen", "Variables are present"]', 1, 'Indicates that the fetus may not tolerate labor. (Williams)'),
    (v_topic_id, '137: Which of the following is a marker of fetal "lung maturity"?', '["AFP", "Lecithin/Sphingomyelin (L/S) ratio > 2.0", "hCG level", "uE3 level"]', 1, 'Assessed via amniocentesis (rarely done now with accurate dating). (Beckmann)'),
    (v_topic_id, '138: "Oligohydramnios" in the third trimester is a common sign of:', '["Fetal renal agenesis", "Placental insufficiency (fetal redistribution of blood away from kidneys)", "Gestational diabetes", "Multiple gestation"]', 1, 'Often seen in IUGR or post-term pregnancies. (Gabbe)'),
    (v_topic_id, '139: A woman at 38 weeks has a "Deepest Vertical Pocket" (DVP) of 1.5 cm on ultrasound. This is:', '["Normal", "Oligohydramnios", "Polyhydramnios", "Indicative of twins"]', 1, 'DVP < 2 cm is the diagnostic criterion for oligohydramnios. (ACOG)'),
    (v_topic_id, '140: What is the primary purpose of "Leopold Maneuvers"?', '["To check for cervical dilation", "To determine fetal lie, presentation, and position", "To measure fundal height", "To assess amniotic fluid"]', 1, 'Manual palpation of the abdomen. (Williams)'),
    (v_topic_id, '141: "Engagement" of the fetal head occurs when:', '["The head enters the pelvic inlet", "The widest diameter (BPD) passes through the pelvic inlet (Station 0)", "The head is at the perineum", "The cervix is 10 cm dilated"]', 1, 'Indicates the head has entered the true pelvis. (Beckmann)'),
    (v_topic_id, '142: Which of the following is an "Adverse Effect" of maternal smoking during pregnancy?', '["IUGR (Small for Gestational Age)", "Placental abruption", "Preterm birth", "All of the above"]', 3, 'Nicotine and CO cause placental vasoconstriction and hypoxia. (ACOG)'),
    (v_topic_id, '143: Maternal use of SSRIs (like Fluoxetine) in the third trimester is associated with a risk of:', '["Heart defects", "Neonatal Adaptation Syndrome (irritability, feeding difficulty)", "Cleft lip", "Limb defects"]', 1, 'Usually mild and self-limiting withdrawal/adaptation symptoms. (Gabbe)'),
    (v_topic_id, '144: Which of the following is the most common cause of "non-immune hydrops fetalis"?', '["ABO incompatibility", "Cardiovascular anomalies", "Parvovirus B19 infection", "Chromosomal abnormalities"]', 1, 'Fetal heart failure is the leading cause. (Williams)'),
    (v_topic_id, '145: "Parvovirus B19" infection in pregnancy can cause fetal:', '["Limb defects", "Aplastic anemia and hydrops fetalis", "Blindness", "Diabetes"]', 1, 'Virus infects fetal erythroid precursors. (Gabbe)'),
    (v_topic_id, '146: Maternal "Varicella" infection in the first 20 weeks of pregnancy carries a risk of:', '["Congenital Varicella Syndrome (skin scarring, limb hypoplasia, eye defects)", "Immediate miscarriage", "Heart block", "None"]', 0, 'Risk is low (~1-2%) but serious. (ACOG)'),
    (v_topic_id, '147: What is the management for a woman exposed to Varicella during pregnancy if she is non-immune?', '["Immediate vaccination", "Varicella-Zoster Immunoglobulin (VZIG)", "Acyclovir for 9 months", "Termination of pregnancy"]', 1, 'VZIG can prevent or attenuate the disease if given within 10 days of exposure. (CDC)'),
    (v_topic_id, '148: Which maternal infection is associated with "periventricular calcifications" and "sensorineural hearing loss" in the neonate?', '["Toxoplasmosis", "Cytomegalovirus (CMV)", "Rubella", "Syphilis"]', 1, 'CMV is the most common congenital infection. (Williams)'),
    (v_topic_id, '149: "Congenital Toxoplasmosis" classically presents with the triad of:', '["Heart defects, cataracts, deafness", "Chorioretinitis, hydrocephalus, and intracranial calcifications", "Snuffles, rash, bone lesions", "Microcephaly, seizures, rash"]', 1, 'Intracranial calcifications in Toxo are usually diffuse/parenchymal (unlike CMV). (Gabbe)'),
    (v_topic_id, '150: What is the most effective way to prevent vertical transmission of Hepatitis B to the neonate?', '["C-section delivery", "Maternal antiviral therapy in the 3rd trimester (if high viral load)", "HBV vaccine and HBIG to the neonate at birth", "Both B and C"]', 3, 'Neonatal immunoprophylaxis is >90% effective. (ACOG)'),
    (v_topic_id, '151: Which of the following is an indication for "early" GDM screening (at the first visit)?', '["History of GDM", "BMI > 30", "Known impaired glucose tolerance", "All of the above"]', 3, 'High-risk women should not wait until 24 weeks. (ACOG)'),
    (v_topic_id, '152: A "Dizygotic" twin pregnancy (fraternal) always results in:', '["Monochorionic/Monoamniotic twins", "Dichorionic/Diamniotic twins", "Monochorionic/Diamniotic twins", "Conjoined twins"]', 1, 'Two separate eggs and two separate sperm. (Williams)'),
    (v_topic_id, '153: If a single fertilized egg (Monozygotic) divides between days 4 and 8 post-fertilization, what is the resulting chorionicity/amnionicity?', '["Dichorionic/Diamniotic", "Monochorionic/Diamniotic", "Monochorionic/Monoamniotic", "Conjoined twins"]', 1, 'The most common type of monozygotic twins (~75%). (Gabbe)'),
    (v_topic_id, '154: If a monozygotic egg divides after day 13, the result is:', '["Monochorionic/Monoamniotic", "Dichorionic/Diamniotic", "Conjoined twins", "Vanishing twin"]', 2, 'Extremely rare. (Williams)'),
    (v_topic_id, '155: What is the primary risk of a "Monoamniotic" twin pregnancy?', '["Twin-to-twin transfusion", "Cord entanglement and fetal death", "Placental abruption", "Gestational diabetes"]', 1, 'Requires intensive monitoring and early delivery (32-34 weeks). (ACOG)'),
    (v_topic_id, '156: "Velamentous Cord Insertion" refers to:', '["Cord inserted into the edge of the placenta", "Cord vessels running through the membranes unprotected by Wharton''s jelly", "Two umbilical arteries", "Short cord"]', 1, 'Increases risk of vasa previa and vessel rupture. (Beckmann)'),
    (v_topic_id, '157: "Vasa Previa" is a condition where:', '["The placenta covers the os", "Fetal vessels run over the internal cervical os", "The cord is prolapsed", "The uterus is ruptured"]', 1, 'Catastrophic bleeding (fetal blood) can occur with ROM. (Gabbe)'),
    (v_topic_id, '158: What is the classic finding for "Vasa Previa" after ROM?', '["Painless maternal bleeding", "Fetal bradycardia or sinusoidal rhythm following painless vaginal bleeding", "Severe abdominal pain", "High fever"]', 1, 'The bleeding is fetal in origin; small amounts cause rapid fetal distress. (Williams)'),
    (v_topic_id, '159: "Succenturiate Lobe" refers to:', '["A placenta with an extra lobe connected by fetal vessels", "A placenta that is too thick", "A placenta with an offset cord", "None of the above"]', 0, 'Risk of vasa previa or retained placenta. (Beckmann)'),
    (v_topic_id, '160: A woman with a "Bicornuate Uterus" is at increased risk for:', '["Malpresentation (e.g., breech)", "Preterm birth", "Miscarriage", "All of the above"]', 3, 'Uterine anomalies limit the space for the growing fetus. (ACOG)'),
    (v_topic_id, '161: Which uterine anomaly is most strongly associated with second-trimester miscarriage and can be treated surgically?', '["Bicornuate uterus", "Septate uterus", "Uterus didelphys", "Arcuate uterus"]', 1, 'Hysteroscopic resection of the septum improves outcomes. (Gabbe)'),
    (v_topic_id, '162: "Placenta Accreta" is defined as:', '["Placenta covers the os", "Placenta attaches directly to the myometrium due to a defective decidua basalis", "Placenta invades through the myometrium", "Placenta invades the bladder"]', 1, 'Often follows a previous C-section or uterine surgery. (Williams)'),
    (v_topic_id, '163: "Placenta Percreta" occurs when:', '["The placenta invades through the entire uterine wall, potentially into the bladder or bowel", "The placenta is partially detached", "The placenta is small", "The cord is short"]', 0, 'Most severe form of accreta spectrum. (Gabbe)'),
    (v_topic_id, '164: What is the primary risk factor for Placenta Accreta?', '["Maternal age", "Multiparity", "Prior Cesarean section and concurrent placenta previa", "Smoking"]', 2, 'The risk increases significantly with the number of prior C-sections. (ACOG)'),
    (v_topic_id, '165: A "Low-lying placenta" is one that is within how many cm of the internal os?', '["0.5 cm", "2 cm", "5 cm", "10 cm"]', 1, 'Usually monitored via follow-up US as most "migrate" away as the uterus grows. (ACOG)'),
    (v_topic_id, '166: Which of the following is a symptom of "Placental Abruption"?', '["Painless bleeding", "Painful vaginal bleeding and firm, tender uterus (hypertonus)", "Absence of fetal movement", "Clear fluid leak"]', 1, 'Premature separation of the placenta from the uterine wall. (Beckmann)'),
    (v_topic_id, '167: What is the most common risk factor for placental abruption?', '["Diabetes", "Maternal hypertension (chronic or gestational)", "Obesity", "Hypothyroidism"]', 1, 'Other risks include cocaine use, trauma, and smoking. (ACOG)'),
    (v_topic_id, '168: "Couvelaire Uterus" is a complication of severe abruption where:', '["The uterus ruptures", "Blood extravasates into the myometrium, appearing bluish", "The uterus is inverted", "The placenta is retained"]', 1, 'May lead to uterine atony. (Williams)'),
    (v_topic_id, '169: Which of the following is the most sensitive test for "Fetomaternal Hemorrhage" (e.g., after trauma)?', '["Ultrasound", "Kleihauer-Betke (KB) test", "CBC", "Liver functions"]', 1, 'Quantifies the amount of fetal RBCs in the maternal circulation. (Gabbe)'),
    (v_topic_id, '170: The Kleihauer-Betke test is used to:', '["Diagnose Down syndrome", "Calculate the required dose of RhoGAM after a large hemorrhage", "Detect infection", "Measure fetal weight"]', 1, 'Ensures enough RhoGAM is given to neutralize the fetal Rh-positive cells. (ACOG)'),
    (v_topic_id, '171: A woman with "Chronic Hypertension" in pregnancy is defined as:', '["BP > 140/90 diagnosed after 20 weeks", "BP > 140/90 present before pregnancy or diagnosed before 20 weeks", "High BP only during labor", "Normal BP with proteinuria"]', 1, 'Increases risk of pre-eclampsia, abruption, and IUGR. (ACOG)'),
    (v_topic_id, '172: "Gestational Hypertension" is defined as:', '["High BP before 20 weeks", "New-onset hypertension (>140/90) after 20 weeks WITHOUT proteinuria or severe features", "High BP with seizures", "Chronic BP"]', 1, 'Usually resolves within 12 weeks postpartum. (Williams)'),
    (v_topic_id, '173: Which of the following medications is first-line for the treatment of hypertension in pregnancy?', '["Labetalol or Nifedipine", "Lisinopril", "Losartan", "Spironolactone"]', 0, 'Methyldopa is also used, but Labetalol/Nifedipine are very common. (ACOG)'),
    (v_topic_id, '174: "Pre-eclampsia" is classically defined as hypertension plus:', '["Headache", "Proteinuria (>300 mg/24h or PCR > 0.3)", "Weight gain", "Low platelets"]', 1, 'Can also be diagnosed without proteinuria if other severe features are present. (ACOG)'),
    (v_topic_id, '175: What are the "Severe Features" of pre-eclampsia?', '["BP > 160/110", "Thrombocytopenia (< 100k)", "Elevated liver enzymes or severe RUQ pain", "All of the above"]', 3, 'Also includes pulmonary edema, cerebral/visual symptoms, and renal insufficiency. (ACOG)'),
    (v_topic_id, '176: "Eclampsia" is defined as:', '["High BP with proteinuria", "Pre-eclampsia with new-onset grand mal seizures", "HELLP syndrome", "Stroke in pregnancy"]', 1, 'A medical emergency. (Beckmann)'),
    (v_topic_id, '177: What is the medication of choice for seizure prophylaxis in a woman with pre-eclampsia with severe features?', '["Phenytoin", "Magnesium Sulfate", "Diazepam", "Levetiracetam"]', 1, 'Superior to anticonvulsants for preventing eclamptic seizures. (Williams)'),
    (v_topic_id, '178: What is the "antidote" for Magnesium Toxicity (loss of DTRs, respiratory depression)?', '["Naloxone", "Calcium Gluconate", "Vitamin K", "Flumazenil"]', 1, '1 gram of 10% calcium gluconate IV. (Gabbe)'),
    (v_topic_id, '179: HELLP syndrome stands for:', '["Hypertension, Edema, Liver, Low Platelets", "Hemolysis, Elevated Liver enzymes, Low Platelets", "Heart, Edema, Lungs, Proteinuria", "None of the above"]', 1, 'A severe variant of pre-eclampsia. (ACOG)'),
    (v_topic_id, '180: The "Hemolysis" in HELLP syndrome is characterized by:', '["Positive Coombs test", "Microangiopathic hemolytic anemia with schistocytes on smear", "Low bilirubin", "High haptoglobin"]', 1, 'Due to RBC fragmentation as they pass through damaged small vessels. (Williams)'),
    (v_topic_id, '181: A woman at 35 weeks with pre-eclampsia WITH severe features should be managed by:', '["Expectant management until 37 weeks", "Immediate delivery", "Strict bed rest at home", "Oral antihypertensives only"]', 1, 'Delivery is the only cure; at 34+ weeks, the risks of continuing outweigh the risks of prematurity. (ACOG)'),
    (v_topic_id, '182: "Intrauterine Growth Restriction" (IUGR) is typically defined as an estimated fetal weight below the:', '["3rd percentile", "10th percentile", "25th percentile", "50th percentile"]', 1, 'Requires umbilical artery Doppler studies to assess fetal well-being. (ACOG)'),
    (v_topic_id, '183: "Asymmetric IUGR" (head sparing) is usually caused by:', '["Chromosomal anomalies", "Congenital infection", "Placental insufficiency (e.g., maternal HTN)", "Early pregnancy insult"]', 2, 'Occurs late in pregnancy; blood is shunted to the brain. (Beckmann)'),
    (v_topic_id, '184: "Symmetric IUGR" (all parameters small) is usually caused by:', '["Preeclampsia", "Smoking", "Constitutional small size", "Early insults like TORCH infections or aneuploidy"]', 3, 'Affects the fetus from the first/early second trimester. (Williams)'),
    (v_topic_id, '185: Which Doppler finding in the Umbilical Artery is most concerning for fetal distress?', '["High resistance", "Absent or Reversed End-Diastolic Flow (AREDF)", "Low resistance", "Normal flow"]', 1, 'Indicates severe placental resistance and imminent fetal compromise. (Gabbe)'),
    (v_topic_id, '186: "Macrosomia" in a diabetic patient increases the risk of what birth complication?', '["Breech presentation", "Shoulder dystocia (head delivered but shoulders stuck)", "Umbilical cord prolapse", "Placenta previa"]', 1, 'Due to larger trunk/shoulder size compared to head. (ACOG)'),
    (v_topic_id, '187: A "McRoberts Maneuver" (hyperflexing the mother''s legs) is used to manage:', '["Breech delivery", "Shoulder dystocia", "Postpartum hemorrhage", "Uterine inversion"]', 1, 'Opens the pelvic outlet and flattens the sacrum. (Williams)'),
    (v_topic_id, '188: "Intrahepatic Cholestasis of Pregnancy" (ICP) typically presents with:', '["Jaundice and abdominal pain", "Intense pruritus (especially palms/soles) without a rash, and elevated bile acids", "High fever", "Rash on the abdomen"]', 1, 'Associated with an increased risk of stillbirth; delivery at 36-37 weeks is often recommended. (ACOG)'),
    (v_topic_id, '189: The medication used to treat Intrahepatic Cholestasis of Pregnancy is:', '["Diphenhydramine", "Ursodeoxycholic acid (Ursodiol)", "Steroid cream", "Cholestyramine"]', 1, 'Improves pruritus and lowers bile acid levels. (Beckmann)'),
    (v_topic_id, '190: "Acute Fatty Liver of Pregnancy" (AFLP) is a rare but life-threatening condition that presents with:', '["Pruritus only", "Liver failure, hypoglycemia, and DIC in the third trimester", "High BP and proteinuria", "Normal labs"]', 1, 'Requires immediate delivery and intensive care. (Williams)'),
    (v_topic_id, '191: Which of the following is the most common cause of "postpartum hemorrhage"?', '["Uterine atony (failure to contract)", "Genital tract lacerations", "Retained placenta", "Coagulopathy"]', 0, 'The "4 Ts": Tone, Trauma, Tissue, Thrombin. (ACOG)'),
    (v_topic_id, '192: First-line medication for uterine atony after oxytocin is:', '["Aspirin", "Methylergonovine (Methergine) or Carboprost (Hemabate)", "Warfarin", "Heparin"]', 1, 'Uterotonic agents. (Williams)'),
    (v_topic_id, '193: "Methylergonovine" (Methergine) is contraindicated in patients with:', '["Asthma", "Hypertension", "Diabetes", "Obesity"]', 1, 'It can cause severe vasoconstriction/hypertensive crisis. (ACOG)'),
    (v_topic_id, '194: "Carboprost" (Hemabate) is contraindicated in patients with:', '["Hypertension", "Asthma", "Diabetes", "Liver disease"]', 1, 'It can cause bronchoconstriction. (ACOG)'),
    (v_topic_id, '195: "Sheehan Syndrome" is postpartum necrosis of the:', '["Liver", "Pituitary gland", "Adrenal glands", "Kidneys"]', 1, 'Caused by severe postpartum hemorrhage/shock. (Beckmann)'),
    (v_topic_id, '196: A "Sinusoidal" fetal heart rate pattern is highly suggestive of:', '["Fetal sleep", "Severe fetal anemia (e.g., from Rh alloimmunization or vasa previa)", "Maternal fever", "Head compression"]', 1, 'A smooth, wave-like baseline; very concerning. (ACOG)'),
    (v_topic_id, '197: "Chorioamnionitis" (Intra-amniotic infection) is typically diagnosed clinically by:', '["Maternal fever and fetal tachycardia", "Uterine tenderness", "Foul-smelling amniotic fluid", "All of the above"]', 3, 'Requires broad-spectrum antibiotics and delivery. (Williams)'),
    (v_topic_id, '198: Which of the following is the most common reason for "Induction of Labor"?', '["Maternal request", "Post-term pregnancy", "Pre-eclampsia", "Fetal macrosomia"]', 1, 'To prevent the risks associated with post-maturity. (ACOG)'),
    (v_topic_id, '199: The "Bishop Score" is used to assess:', '["Fetal well-being", "Cervical readiness for induction", "Risk of C-section", "Fetal weight"]', 1, 'Higher score (> 8) predicts a successful vaginal delivery. (Beckmann)'),
    (v_topic_id, '200: "Amniotomy" (Artificial Rupture of Membranes) is often performed to:', '["Induce or augment labor", "Place internal monitors (IUPC/FSE)", "Check for meconium", "All of the above"]', 3, 'Should only be done if the head is well-engaged to avoid cord prolapse. (Gabbe)');
